-- 042. Ответы шефа на вопросы брифинга — живым языком, под озвучку
update characters set fixed_questions = '[{"q": "Кто мне поможет?", "a": "— Сеитова. Следы, вещдоки — это всё к ней. Абишев на картотеках сидит: адресное бюро, узел связи, электросети — всё через него. Кан — в морге. Ну и Бейсенов, доцент, он у нас на этой неделе. Они все здесь, в здании. Давай, иди."}, {"q": "Что не так с этим «угаром»?", "a": "— А может, и ничего… Только вскрытия-то не было. А мне уже отказной на подпись несут. Начни с морга — Кан направление ждёт. И на Кок-Тобе съезди. Пока там снегом всё не замело."}]'::jsonb where id = '57949d2d-0b2d-5c04-812c-5849e9441857';
select jsonb_array_length(fixed_questions) as questions from characters where id = '57949d2d-0b2d-5c04-812c-5849e9441857';
